window.renderAnnualCase=(t,href)=>{
 const images=()=>[1,2,3,4].map((n)=>`<img src="assets/annual-2025/article-${n}.webp" alt="${t('2025 业绩成绩单长图，第','2025 results infographic, part ')}${n}${t('部分','')}" decoding="async">`).join('');
 return `<section class="project-header"><div class="project-title"><h1 class="page-title">${t('中远海运港口<br>2025 业绩成绩单','COSCO SHIPPING Ports<br>2025 Results')}</h1></div><div class="project-info"><dl><div><dt>${t('项目 / 品牌','Project / Brand')}</dt><dd>${t('中远海运港口有限公司','COSCO SHIPPING Ports Limited')}</dd></div><div><dt>${t('内容年度','Reporting year')}</dt><dd>2025</dd></div><div><dt>${t('服务类别','Category')}</dt><dd>${t('数据内容与信息可视化','Data & Information Design')}</dd></div><div><dt>${t('服务内容','Services')}</dt><dd>${t('业绩长图 / 数据可视化 / 公众号视觉','Results infographic / Data visualisation / WeChat design')}</dd></div></dl><div class="project-description"><span class="number">${t('项目介绍','About the project')}</span><p>${t('以公众号长图呈现中远海运港口 2025 年度业绩与业务进展，将财务数据、全球布局与运营亮点组织为连续的阅读叙事。蓝色贯穿整篇，结合图表、地图与场景插画，建立清晰的信息层级与视觉节奏。','A long-form WeChat infographic presenting COSCO SHIPPING Ports’ 2025 results and business developments. Financial data, the global network and operational highlights form a continuous visual narrative, using blue, charts, maps and illustrated scenes to structure the reading experience.')}</p></div></div></section><section class="annual-stage"><div class="annual-note"><p>${t('将鼠标移入手机屏幕，上下滚动查看完整作品。手机上可直接滑动。','Scroll inside the phone to explore the complete work. On mobile, swipe within the screen.')}</p><p class="annual-language-note">${t('作品画面保留原始中文。','The original artwork is presented in Chinese.')}</p><div class="annual-actions"><button type="button" data-annual-open>${t('展开阅读','Expand artwork')} ↗</button><button type="button" data-annual-reset>${t('回到开头','Start again')} ↑</button></div><div class="annual-progress" role="progressbar" aria-label="${t('阅读进度','Reading progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span></span></div><small class="annual-percent">0%</small></div><div class="annual-device"><div class="annual-status" aria-hidden="true"><span class="annual-time">09:41</span><span class="annual-island"></span><span class="annual-status-icons"><svg viewBox="0 0 20 15"><path d="M1 14h3V10H1zm5 0h3V7H6zm5 0h3V4h-3zm5 0h3V1h-3z"/></svg><svg viewBox="0 0 20 15"><path d="M1 4Q10-3 19 4L16 7Q10 2 4 7zm5 5q4-4 8 0l-4 5z"/></svg><i></i></span></div><span class="annual-side-button" aria-hidden="true"></span><div class="annual-screen" tabindex="0" role="region" aria-label="${t('可滚动阅读的年报长图','Scrollable annual results artwork')}">${images()}</div><div class="annual-homebar" aria-hidden="true"></div></div></section><dialog class="annual-dialog" aria-label="${t('完整作品','Complete artwork')}"><div class="annual-dialog-top"><span>${t('2025 业绩成绩单','2025 Results')}</span><button type="button" data-annual-close>${t('关闭','Close')} ×</button></div><div class="annual-expanded">${images()}</div></dialog><section class="annual-qr-footer" style="text-align:center;background:#fff;padding:80px 20px"><a href="https://mp.weixin.qq.com/s/L2bITpiXMQ2Uh3AF8PxhCw" target="_blank" rel="noopener noreferrer" aria-label="2025业绩成绩单公众号原文"><img src="assets/annual-2025/wechat-qr.png" alt="扫描二维码查看2025业绩成绩单原文" width="200" height="200" style="display:block;width:160px;height:160px;margin:auto;opacity:1!important;transform:none!important"></a><p style="font-size:14px;margin:20px 0 0">${t('扫一扫，在公众号浏览','Scan to view on WeChat')}</p></section><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=ai4s')}"><span>${t('下一个项目','Next project')}</span><strong>AI4S ↗</strong></a></section>`;
};
document.addEventListener('DOMContentLoaded',()=>{
 const screen=document.querySelector('.annual-screen');if(!screen)return;
 const bar=document.querySelector('.annual-progress');
 const update=()=>{const max=screen.scrollHeight-screen.clientHeight;const n=max>0?Math.round(screen.scrollTop/max*100):0;bar.setAttribute('aria-valuenow',n);bar.firstElementChild.style.width=n+'%';document.querySelector('.annual-percent').textContent=n+'%'};
 screen.addEventListener('scroll',update,{passive:true});screen.querySelectorAll('img').forEach(im=>im.addEventListener('load',update));update();
 document.querySelector('[data-annual-reset]').addEventListener('click',()=>screen.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 const dialog=document.querySelector('.annual-dialog');let opener;
 document.querySelector('[data-annual-open]').addEventListener('click',e=>{opener=e.currentTarget;dialog.showModal();document.body.classList.add('annual-modal-open')});
 document.querySelector('[data-annual-close]').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('close',()=>{document.body.classList.remove('annual-modal-open');opener?.focus()});
 dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
});
